UPDATE loans
SET status = 2, loaned_at = NOW(), due_date = DATE_ADD(CURDATE(), INTERVAL 14 DAY)
WHERE id = #{id}

UPDATE members
SET suspended_until = DATE_ADD(CURDATE(), INTERVAL #{days} DAY)
WHERE id = #{memberId}

UPDATE loans
SET due_date = DATE_ADD(due_date, INTERVAL 7 DAY), extend_count = extend_count + 1
WHERE id = #{id}
